from nlib import *
S=[]
def G(id,title,sc,sm,b,d,e,f,dy,sec,bk="ANP",mol=(),kn=("organelles_overview",),made=(),par=(),proc=(),cert="C1",oq=None,kind="organelle"):
    S.append(N(id,title,kind,"cell",sc,sm,b,d,e,f,dy,par=par,made=made,proc=proc,refs=[(bk,sec),("BIO","4.3")] if bk=="ANP" else [(bk,sec)],kn=kn,mol=list(mol),cert=cert,oq=oq))
G("nucleus","Nucleus",6e-6,"The membrane-bound compartment that holds the cell's DNA.","The nucleus is the cell's control room: it stores DNA and decides which genes are read.","DNA is wrapped around histone proteins to form chromatin; pores in the double membrane control traffic.","≈ 2 m of DNA (≈ 6.4×10^9 bp diploid) packed in a ≈ 6 µm nucleus; ≈ 2,000-5,000 nuclear pores; nuclear lamina; nucleolus makes ribosomal RNA.",[("Diameter","≈ 6 µm"),("DNA per cell","≈ 2 m"),("Base pairs (diploid)","≈ 6.4×10^9")],"If you unwound the DNA from one cell it would be about two meters long.","3.3",mol=["1bna","dgmp","dcmp","damp","dtmp"],kn=("dna_structure","chromatin_genome"))
G("mitochondrion","Mitochondrion",1.5e-6,"The organelle that makes most of the cell's ATP.","Mitochondria burn fuel with oxygen to make ATP, the cell's energy currency.","They have two membranes, and an inner membrane folded into cristae. They have their own small circular DNA.","Electron transport complexes I-IV pump protons; ATP synthase uses the proton gradient (≈ 150-180 mV); ≈ 16.6 kb mtDNA encoding 13 proteins; inherited maternally.",[("Length","≈ 1-2 µm"),("mtDNA","≈ 16.6 kb, 37 genes"),("ATP yield","≈ 30 per glucose")],"Mitochondria likely descend from bacteria that moved into ancestral cells about 2 billion years ago.","3.2",mol=["atp","adp","nadh","nad_plus","fad","ubiquinone_q1","pyruvate","citrate"],kn=("mitochondria_org","oxidative_phosphorylation"),proc=["cellular_respiration"])
G("ribosome","Ribosome",2.5e-8,"A molecular machine that builds proteins from instructions in mRNA.","Ribosomes read genetic messages and string amino acids together into proteins.","They are made of RNA and protein and exist free or attached to the rough ER.","80S eukaryotic ribosome (60S + 40S) ≈ 4.3 MDa; the peptidyl transferase center is RNA-catalyzed (a ribozyme); ≈ 3-6 amino acids added per second in eukaryotes.",[("Diameter","≈ 25 nm"),("Mass","≈ 4.3 MDa"),("Speed","≈ 3-6 aa/s")],"The catalytic core of the ribosome is RNA, not protein.","3.4",mol=["aa_gly","aa_ala","aa_leu","aa_met","aa_trp"],kn=("central_dogma",),proc=["protein_synthesis"])
G("endoplasmic_reticulum","Endoplasmic reticulum",1e-6,"A network of membranes that makes proteins and lipids.","The ER is the cell's workshop: rough ER (with ribosomes) makes proteins; smooth ER makes fats and handles calcium.","It can make up over half of a cell's membrane.","Co-translational translocation via Sec61; N-glycosylation, disulfide formation, unfolded protein response; SR in muscle stores Ca2+.",[("Membrane share","≈ 50%+ of cell membrane"),("Lumen Ca2+","≈ 0.1-0.5 mM")],"In muscle cells a specialized ER called the sarcoplasmic reticulum stores the calcium that triggers contraction.","3.2",mol=["popc","cholesterol","calcium_carbonate_unit"],kn=("organelles_overview",),proc=["protein_synthesis"])
G("golgi_apparatus","Golgi apparatus",1e-6,"A stack of membrane sacs that sorts and ships proteins.","The Golgi puts final touches on proteins and packages them for delivery.","Vesicles bud off carrying cargo to the cell surface or other organelles.","cis, medial, trans cisternae; glycan processing; sorting via mannose-6-phosphate for lysosomal enzymes; cargo exit in carriers.",[("Cisternae","≈ 4-8 per stack"),("Role","modify, sort")],"It was discovered by Camillo Golgi in 1898 using a silver stain.","3.2",mol=["n_acetylglucosamine","galactose"],kn=("organelles_overview",),proc=["protein_synthesis"])
G("lysosome","Lysosome",5e-7,"An acidic recycling compartment containing digestive enzymes.","Lysosomes break down worn-out parts and swallowed germs.","Their inside is acidic (pH ≈ 4.5-5).","Contain ≈ 50 hydrolases; V-ATPase acidifies; autophagy delivers cargo; lysosomal storage diseases arise from enzyme deficiencies.",[("Diameter","≈ 0.1-1 µm"),("Internal pH","≈ 4.5-5")],"Lysosomal storage diseases such as Tay-Sachs result from one missing enzyme.","3.2",mol=["hydrogen_peroxide"],kn=("organelles_overview",))
G("peroxisome","Peroxisome",5e-7,"A small compartment that handles fatty-acid oxidation and neutralizes peroxides.","Peroxisomes break down certain fats and detoxify harmful by-products.","They hold catalase to convert hydrogen peroxide to water.","β-oxidation of very-long-chain fatty acids; plasmalogen synthesis; Zellweger spectrum disorders.",[("Diameter","≈ 0.5 µm")],"Peroxisomes in liver cells help detoxify a portion of the alcohol you drink.","3.2",mol=["hydrogen_peroxide","stearic_acid"],kn=("organelles_overview",))
G("cell_membrane","Cell membrane",7.5e-9,"A flexible oily barrier that surrounds every cell.","The membrane is a double layer of fat-like molecules that controls what enters and leaves.","Proteins in it act as gates, pumps and receptors.","Fluid mosaic bilayer ≈ 5-7 nm thick; phospholipids, cholesterol (up to ≈ 40 mol% in some), lipid rafts; Na+/K+-ATPase uses ≈ 20-30% of cell ATP in many cells.",[("Thickness","≈ 7.5 nm"),("Resting voltage","≈ -70 mV (neurons)")],"If a cell were scaled up to a 10 m wide room, its membrane would be only about 7 mm thick.","3.1",mol=["popc","cholesterol","sphingosine"],kn=("membrane_structure","membrane_transport"))
G("cytoskeleton","Cytoskeleton",1e-8,"A scaffold of protein filaments giving cells shape and movement.","Fibers inside the cell hold its shape and act as tracks for moving cargo.","Three types: actin filaments, intermediate filaments, microtubules.","Actin ≈ 7 nm, intermediate ≈ 10 nm, microtubule ≈ 25 nm; motors kinesin and dynein walk on microtubules; myosin on actin.",[("Microtubule diameter","≈ 25 nm"),("Actin diameter","≈ 7 nm")],"Kinesin walks along microtubules with ≈ 8 nm steps, like a tiny two-legged robot.","3.2",mol=["atp"],kn=("cytoskeleton_motors",))
G("sarcomere","Sarcomere",2.5e-6,"The repeating contractile unit of striated muscle.","A sarcomere is a tiny stack of sliding filaments that shortens to generate force.","Thin actin filaments slide past thick myosin filaments, pulling Z-discs together.","≈ 2.2 µm at rest; thick filament ≈ 1.6 µm, thin ≈ 1 µm; titin spans Z-disc to M-line; force-length relation peaks at ≈ 2.0-2.2 µm.",[("Resting length","≈ 2.2-2.5 µm"),("Shortening","≈ 70% of rest")],"A single muscle fiber contains thousands of sarcomeres lined up end to end.","10.2",mol=["atp","creatine"],kn=("muscle_contraction",),proc=["muscle_contraction"],kind="structure")
save("body_organelles",S)
